const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9']/g, '');

/** Start time (seconds) of a word/phrase near a given time. */
export const cue = (phrase: string, near = 0, occurrence = 0): number => {
  const target = phrase.toLowerCase().split(/\s+/).map(norm).filter(Boolean);
  if (!target.length) return near;
  const hits: number[] = [];
  for (let i = 0; i <= WORDS.length - target.length; i++) {
    let ok = true;
    for (let j = 0; j < target.length; j++) {
      if (norm(WORDS[i + j].w) !== target[j]) { ok = false; break; }
    }
    if (ok) hits.push(WORDS[i].s);
  }
  if (!hits.length) {
    // fallback: prefix match of first token
    const loose = WORDS.filter((w) => norm(w.w).startsWith(target[0])).map((w) => w.s);
    if (!loose.length) return near;
    loose.sort((a, b) => Math.abs(a - near) - Math.abs(b - near));
    return loose[Math.min(occurrence, loose.length - 1)];
  }
  hits.sort((a, b) => Math.abs(a - near) - Math.abs(b - near));
  return hits[Math.min(occurrence, hits.length - 1)];
};

/** End time (seconds) of a word/phrase near a given time. */
export const cueEnd = (phrase: string, near = 0, occurrence = 0): number => {
  const start = cue(phrase, near, occurrence);
  const target = phrase.toLowerCase().split(/\s+/).map(norm).filter(Boolean);
  for (let i = 0; i < WORDS.length; i++) {
    if (Math.abs(WORDS[i].s - start) < 0.001) return WORDS[Math.min(i + target.length - 1, WORDS.length - 1)].e;
  }
  return start;
};

export const sent = (i: number) => SENTENCES[i];
